import { Button } from "../components/ui/Button";

export function HomePage() {
  return (
    <main className="app-shell">
      <p className="eyebrow">Workspace</p>
      <h1>Starter route</h1>
      <Button onClick={() => document.documentElement.classList.toggle("dark")}>
        Toggle theme
      </Button>
    </main>
  );
}
@import "tailwindcss";

:root {
  color-scheme: light;
  --color-bezel: #efeeea;
  --color-panel: #ffffff;
  --color-text: #141312;
  --color-border: #d8d6d1;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
}

:root.dark {
  color-scheme: dark;
  --color-bezel: #141312;
  --color-panel: #1d1c1a;
  --color-text: #f5f4f0;
  --color-border: #34322f;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  color: var(--color-text);
  background: var(--color-bezel);
}

.app-shell {
  width: min(100% - 32px, 1120px);
  margin: 16px auto;
  padding: 24px;
  border: 1px solid var(--color-border);
  border-radius: 12px;
  background: var(--color-panel);
}

.eyebrow { font: 600 12px/1.2 ui-monospace, monospace; }

.button,
.focus-target {
  display: inline-flex;
  min-width: 44px;
  min-height: 44px;
  align-items: center;
  justify-content: center;
}

.button:focus-visible,
.focus-target:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}
import type { ButtonHTMLAttributes } from "react";

type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement>;

export function Button({ className = "", ...props }: ButtonProps) {
  return <button className={`button ${className}`.trim()} {...props} />;
}
import { HomePage } from "./pages/HomePage";

export function AppRouter() {
  const pathname = window.location.pathname.replace(/\/$/, "") || "/";

  if (pathname === "/") return <HomePage />;

  return (
    <main className="app-shell">
      <h1>Route not found</h1>
      <a className="focus-target" href="/">Return home</a>
    </main>
  );
}
import { expect, test } from "@playwright/test";

test("starter route renders without horizontal overflow", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("heading", { name: "Starter route" })).toBeVisible();
  const widths = await page.evaluate(() => ({
    viewport: document.documentElement.clientWidth,
    document: document.documentElement.scrollWidth,
  }));
  expect(widths.document).toBeLessThanOrEqual(widths.viewport);
});
